// Build the judge's state from the REAL machine, never from a declaration.
//
// Rules applied here, every one of them paid for:
//   - one narrow judgment per question, never "which action should I take"
//   - the escalation case phrased as `true`
//   - criteria are concrete situations, not adverbs
//   - noul criteria use true/false, so they port to a local model unchanged
//   - the model is PINNED: thresholds tuned against one version mean
//     nothing on a model that changes underneath them
//   - NOTHING THE QUESTION DOES NOT NEED. Measured on this machine, same
//     instant, same questions: carrying a `context_capped` boolean on every
//     slot dropped `node_unfit` from 0.94 to 0.87 — from a clear verdict to
//     the grey zone, on a case that has an obvious answer. The field was
//     true information and completely irrelevant to the question. Padding
//     the state does not make a judgment safer, it makes it mushier.

const obs = $input.first().json;
const live = obs.slots_live || {};

// A slot can carry an agent run if it is really serving AND holds a card.
// A CPU model always answers — that is its job — but it cannot hold a
// twenty-turn thread, so it does not count here.
//
// This is deliberately STRUCTURAL rather than a name match. An earlier
// version tested the slot name against a regex of model sizes and quietly
// reported zero capable slots on a machine where three were serving,
// because the names did not happen to contain "14b" or "27b". A rule that
// depends on how you named things breaks when you rename them.
const serving = Object.entries(live)
  .filter(([, s]) => s.status === 'serving')
  .map(([name, s]) => ({ name, card: s.card }));

const gpu = serving.filter((s) => s.card !== 'cpu').map((s) => s.name);
const cpu = serving.filter((s) => s.card === 'cpu').map((s) => s.name);

const state = {
  gpu_slots_serving: gpu,
  cpu_slots_serving: cpu,
  swap_in_progress: Object.keys(obs.loading || {}),
  manual_containers: obs.manual_containers || [],
  house_rule:
    'an agent run needs a model resident in card memory; a CPU model ' +
    'always answers but cannot hold a twenty-turn thread',
};

const questions = {
  node_unfit: {
    type: 'noul',
    instructions:
      'Is the node UNFIT to receive an agent run, meaning no slot is serving a model able to hold a twenty-turn thread?',
    criteria: {
      true: 'No suitable model is running on a graphics card: the list of capable slots is empty, or only CPU slots answer',
      false: 'At least one slot serves a model resident in card memory, able to hold the thread',
    },
  },
  work_to_preserve: {
    type: 'noul',
    instructions:
      'Is work currently in progress on this node that a configuration swap would interrupt?',
    criteria: {
      true: 'A swap is already running, or a manually started container holds a card, or a game is running',
      false: 'Nothing that a swap would disturb',
    },
  },
};

return [{ json: { state, model: 'jev-1.13.0', questions } }];

// The guard refuses, and says why. Never a technical error.
const a = $('Judge decides').first().json.answers;
return [{ json: {
  allowed: false,
  reason: 'work in progress on the node',
  retry_in_s: 300,
  noul_work_to_preserve: a.work_to_preserve.noul,
  noul_node_unfit: a.node_unfit.noul,
}}];

// The guard allows: the node already serves a capable model.
const a = $('Judge decides').first().json.answers;
const s = $('Build the state').first().json.state;
return [{ json: {
  allowed: true,
  reason: 'the node already serves a capable model',
  capable_slots: s.gpu_slots_serving,
  noul_node_unfit: a.node_unfit.noul,
  noul_work_to_preserve: a.work_to_preserve.noul,
}}];

// Only allow if the swap ACTUALLY completed.
// A slot that was requested is not a slot that is serving.
const r = $input.first().json;
const ok = r.state === 'served' || r.state === 'already_serving';
return [{ json: {
  allowed: ok,
  reason: 'swap: ' + r.state,
  slot_requested: r.slot || null,
  wait_s: r.duration_s ?? r.estimated_wait_s ?? 0,
}}];

// Archive the pair, for a future local specialisation.
// One line per decision, never overwritten: this is the training corpus.
const remote = $('Judge decides').first().json.answers;
let local = null;
try { local = $('Local judge in shadow').first().json.answers; } catch (e) { local = null; }

const flat = (o) => Object.fromEntries(
  Object.entries(o).map(([k, v]) => [k, v.noul ?? v.choice]));

return [{ json: {
  when: new Date().toISOString(),
  question_set: 'guard-before-run',
  state: $('Build the state').first().json.state,
  remote: flat(remote),
  local: local ? flat(local) : null,
  // Agreement is computed later by the evaluator; here we only record.
  agreement: local ? Object.keys(remote).every(
    (k) => local[k] !== undefined &&
      ((remote[k].noul ?? 0) > 0.5) === ((local[k].noul ?? 0) > 0.5)) : null,
}}];

// Escalation is not a decision. The guard refuses, says why, and names the
// fact that a human has been asked.
const a = $('Judge decides').first().json.answers;
return [{ json: {
  allowed: false,
  reason: 'grey zone: the judge does not decide, a human has been notified',
  retry_in_s: 600,
  noul_node_unfit: a.node_unfit.noul,
  noul_work_to_preserve: a.work_to_preserve.noul,
}}];
